# A/V83zz_dispatch_run4b: writes the run-4b job files (V844-V84c: Study 3 across OLMo 3 7B training checkpoints, SFT and DPO) into
# runner/jobs_pending; generated by make_v6_jobs.py run4b (texts stored zlib-compressed, base64).
import zlib as _zl, base64 as _b64
_J = json.loads(_zl.decompress(_b64.b64decode("")).decode())
_QD = ROOT + "/jobs_pending"; _n = 0
for _nm, _src in sorted(_J.items()):
    if not any(os.path.exists(f"{ROOT}/{d}/{_nm}.py") for d in ("jobs_pending", "jobs_running", "jobs_done", "jobs_failed")):
        open(f"{_QD}/{_nm}.py.tmp", "w", encoding="utf-8").write(_src); os.replace(f"{_QD}/{_nm}.py.tmp", f"{_QD}/{_nm}.py"); _n += 1
log(f"V83zz dispatch: {_n} run-4b job files written"); beat("V83zz dispatch ok")
